/*************************************************
 * Name:        _mulrnd32
 *
 * Description: multiply two fixed-point numbers in Q32.32 format
 *              and round the result to nearest integer
 *
 * Arguments:   - int32_t x: first multiplicand
 *              - int32_t y: second multiplicand
 *
 * Returns:     - rounded product
 **************************************************/
static inline int32_t _mulrnd16(const int32_t x, const int32_t y)
{
    __int64_t r = ((__int64_t)x * (__int64_t)y) + (1 << 15);
    return r >> 16;
}

/*************************************************
 * Name:        _complex_mul_real
 *
 * Description: multiply two complex numbers and return the real part
 *
 * Arguments:   - complex_fp32_16 x: first multiplicand
 *              - complex_fp32_16 y: second multiplicand
 *
 * Returns:     - real part of the product
 **************************************************/
static inline int32_t _complex_mul_real(const complex_fp32_16 x, const complex_fp32_16 y)
{
    return _mulrnd16(x.real, y.real) - _mulrnd16(x.imag, y.imag);
}

/*************************************************
 * Name:        _complex_mul_imag
 *
 * Description: multiply two complex numbers and return the imaginary part
 *
 * Arguments:   - complex_fp32_16 x: first multiplicand
 *              - complex_fp32_16 y: second multiplicand
 *
 * Returns:     - imaginary part of the product
 **************************************************/
static inline int32_t _complex_mul_imag(const complex_fp32_16 x, const complex_fp32_16 y)
{
    return _mulrnd16(x.real, y.imag) + _mulrnd16(x.imag, y.real);
}

/*************************************************
 * Name:        _complex_mul
 *
 * Description: multiply two complex numbers
 *
 * Arguments:   - complex_fp32_16 *r: pointer to output complex number
 *              - complex_fp32_16 x: first multiplicand
 *              - complex_fp32_16 y: second multiplicand
 **************************************************/
static void _complex_mul(complex_fp32_16 *r, const complex_fp32_16 x, const complex_fp32_16 y)
{
    r->real = _complex_mul_real(x, y);
    r->imag = _complex_mul_imag(x, y);
}

/*************************************************
 * Name:        complex_fp_sqabs
 *
 * Description: compute squared absolute value of a complex number
 *
 * Arguments:   - complex_fp64_32 x: input complex number
 * 
 * Returns:     - squared absolute value
 **************************************************/
int64_t complex_fp_sqabs(complex_fp32_16 x)
{
    return _mulrnd16(x.real, x.real) + _mulrnd16(x.imag, x.imag);
}

/*************************************************
 * Name:        fft_init_and_bitrev
 *
 * Description: initialize and bit-reverse input polynomial
 *
 * Arguments:   - complex_fp32_16 r[N]: pointer to output array of complex numbers
 *              - const poly *x: pointer to input polynomial
 **************************************************/
void fft_init_and_bitrev(complex_fp32_16 r[FFT_N], const poly *x) {
    int i, inv_i;
    int c;

#if DARTS_MODE == 128 || DARTS_MODE ==256 
    for (i = 0; i < FFT_N; i++) {
        inv_i = brv9[i];
        c = x->coeffs[i];
        r[inv_i].real = c * roots[i].real;
        r[inv_i].imag = c * roots[i].imag;
    }   

#elif DARTS_MODE == 512
    for (i = 0; i < FFT_N; i++) {
        inv_i = brv10[i];
        c = x->coeffs[i];
        r[inv_i].real = c * roots[i].real;
        r[inv_i].imag = c * roots[i].imag;
    }
    
#endif
}

/*************************************************
 * Name:        fft
 *
 * Description: in-place Cooley-Tukey FFT
 *
 * Arguments:   - complex_fp32_16 data[N]: pointer to input/output array of complex numbers
 **************************************************/
void fft(complex_fp32_16 data[FFT_N]) {
    unsigned int r, m, md2, n, k, even, odd, twid;
    complex_fp32_16 u, t;

    for (r = 1; r <= FFT_LOGN; r++) {
        m = 1 << r;
        md2 = m >> 1;
        for (n = 0; n < FFT_N; n += m) {
            for (k = 0; k < md2; k++) {
                even = n + k;
                odd = even + md2;
                twid = k << (FFT_LOGN - r + 1);

                u = data[even];
                _complex_mul(&t, roots[twid], data[odd]);
                data[even].real = u.real + t.real;
                data[even].imag = u.imag + t.imag;
                data[odd].real = u.real - t.real;
                data[odd].imag = u.imag - t.imag;
            }
        }
    }
} 